<main class="container">
<div class="page-heading"><div><h1>Rent Payments and Arrears</h1><p>Record rent payments, review payment history and monitor estimated balances for active tenancies.</p></div><a class="button-link" href="<?= e(base_url('?page=tenants')) ?>">Manage tenants</a></div>
<?php if ($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?>
<section class="panel"><h2>Payment overview</h2><div class="stat-grid"><div class="stat"><span>Payments recorded</span><strong><?= (int)($paymentSummary['paymentCount'] ?? 0) ?></strong></div><div class="stat"><span>Total rent received</span><strong>₦<?= number_format((float)($paymentSummary['totalReceived'] ?? 0), 2) ?></strong></div><div class="stat"><span>Active tenancies</span><strong><?= count($activeTenancies) ?></strong></div></div></section>
<section class="panel"><h2>Record a rent payment</h2>
<?php if (!$activeTenancies): ?><p>There are no active tenancies available for payment recording. Register a tenant and create an active tenancy first. <a href="<?= e(base_url('?page=tenants')) ?>">Manage tenants</a>.</p><?php else: ?>
<form method="post" action="<?= e(base_url('?page=payments')) ?>">
<?= csrf_field() ?><input type="hidden" name="action" value="record">
<label for="tenancyId">Tenant and rental unit</label><select id="tenancyId" name="tenancyId" required><option value="">Select an active tenancy</option><?php foreach ($activeTenancies as $item): ?><option value="<?= (int)$item['tenancyId'] ?>"><?= e($item['fullName'] . ' — ' . $item['propertyName'] . ' / ' . $item['unitNumber'] . ' (₦' . number_format((float)$item['annualRent'], 2) . ' monthly)') ?></option><?php endforeach; ?></select>
<div class="form-grid"><div><label for="amount">Amount received (₦)</label><input id="amount" name="amount" type="number" min="0.01" max="99999999.99" step="0.01" required placeholder="e.g. 150000"></div><div><label for="paymentDate">Payment date</label><input id="paymentDate" name="paymentDate" type="date" max="<?= e(date('Y-m-d')) ?>" required value="<?= e(date('Y-m-d')) ?>"></div></div>
<div class="form-grid"><div><label for="method">Payment method</label><select id="method" name="method" required><option value="cash">Cash</option><option value="transfer">Bank transfer</option><option value="other">Other</option></select></div><div><label for="periodCovered">Annual rent period covered (optional)</label><input id="periodCovered" name="periodCovered" maxlength="50" placeholder="e.g. 30 Oct 2026 – 29 Oct 2027"></div></div>
<label for="receiptNumber">Receipt / transaction reference (optional)</label><input id="receiptNumber" name="receiptNumber" maxlength="50" placeholder="e.g. RCP-2026-001">
<p class="form-hint">Record only payments actually received. For bank transfers, verify the funds in your bank account before recording the payment.</p>
<button type="submit">Record payment</button>
</form><?php endif; ?></section>
<section class="panel"><h2>Estimated rent balances</h2><p class="form-hint">The estimate counts each annual rental period from the tenancy start month through today (or tenancy end month). Confirm the agreed rent schedule before relying on an arrears figure.</p>
<?php if (!$activeTenancies): ?><p>No active tenancies to display.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tenant</th><th>Property / Unit</th><th>Yearly rent</th><th>Total received</th><th>Estimated rent due</th><th>Estimated balance</th></tr></thead><tbody>
<?php foreach ($activeTenancies as $item): ?><tr><td><?= e($item['fullName']) ?></td><td><?= e($item['propertyName'] . ' / ' . $item['unitNumber']) ?></td><td>₦<?= number_format((float)$item['annualRent'], 2) ?></td><td>₦<?= number_format((float)$item['totalPaid'], 2) ?></td><td>₦<?= number_format((float)$item['rentDue'], 2) ?></td><td><?php if ($item['balance'] > 0): ?><strong>₦<?= number_format((float)$item['balance'], 2) ?></strong><?php elseif ($item['credit'] > 0): ?><span class="status occupied">Credit ₦<?= number_format((float)$item['credit'], 2) ?></span><?php else: ?><span class="status vacant">₦0.00</span><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
<section class="panel"><h2>Payment history</h2><?php if (!$payments): ?><p>No payments have been recorded yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Tenant</th><th>Property / Unit</th><th>Amount</th><th>Method</th><th>Period covered</th><th>Reference</th></tr></thead><tbody>
<?php foreach ($payments as $payment): ?><tr><td><?= e($payment['paymentDate']) ?></td><td><?= e($payment['fullName']) ?></td><td><?= e($payment['propertyName'] . ' / ' . $payment['unitNumber']) ?></td><td>₦<?= number_format((float)$payment['amount'], 2) ?></td><td><?= e(ucfirst($payment['method'])) ?></td><td><?= e($payment['periodCovered'] ?? '—') ?></td><td><?= e($payment['receiptNumber'] ?? '—') ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
</main>
